def parse_limit(text):
    if not isinstance(text, str) or not 1 <= len(text) <= 3 or not text.isascii() or not text.isdecimal():
        raise ValueError('expected one to three ASCII decimal digits')
    parsed = int(text)
    if not 1 <= parsed <= 255:
        raise ValueError('expected a value from 1 through 255')
    return parsed
